import 'dart:convert';
import 'dart:io';
import 'dart:typed_data';

import 'package:edupaint_flutter_study/rust_document.dart';
import 'package:flutter_test/flutter_test.dart';

// Authentic, decoded 32×24 fixtures generated by generate-import-fixtures.py.
// Embedded here so native ABI tests do not depend on a local report directory.
final _rgb = base64Decode(
  'iVBORw0KGgoAAAANSUhEUgAAACAAAAAYCAIAAAAUMWhjAAAASUlEQVR42mN4pqxBEtLY'
  '4kYSYhi1YNSCoWHBfzDAZeKWlACsaERZgB9RaoFGwB38CJcFHw4rE4NGLaCCBWiI'
  'SHNHLRi1YChZAAAJHCzBGgENWgAAAABJRU5ErkJggg==',
);
final _rgba = base64Decode(
  'iVBORw0KGgoAAAANSUhEUgAAACAAAAAYCAYAAACbU/80AAAAYUlEQVR42mN4pqzBQAA7'
  '4MMaW9waCOD/+DDDqANGHTDqgEHhgP///4MxIQdsSQnAhhtgeNQBNE8DNHGARsAdQtgB'
  'hgk54MNhZWz4Pz486oCh5QBsGIelow4YdcCoA4aOAwBIAXwQRrActQAAAABJRU5ErkJggg==',
);

int _version(Uint8List project) =>
    ByteData.sublistView(project).getUint16(8, Endian.little);

void _addRectangle(RustDocument document) {
  document.addShape(
    VectorKind.rectangle,
    const DocumentPoint(2, 3),
    const DocumentPoint(12, 14),
    rgb: 0x123456,
    width: 2,
    fillRgb: 0xabcdef,
  );
}

void main() {
  final available = Platform.environment['EDUPAINT_CORE_LIBRARY'] != null;

  group('hybrid document ABI', () {
    for (final fixture in {'RGB': _rgb, 'RGBA': _rgba}.entries) {
      test('${fixture.key} metadata, owned bytes and image-only history', () {
        final input = Uint8List.fromList(fixture.value);
        final document = RustDocument.fromBackgroundPng(input);
        try {
          final info = document.backgroundInfo!;
          expect((document.width, document.height), (32, 24));
          expect((info.width, info.height), (32, 24));
          expect(info.byteCount, fixture.value.length);
          expect(identical(info, document.backgroundInfo), isTrue);
          expect(document.count, 0);
          expect(document.canUndo, isFalse);
          expect(document.canRedo, isFalse);
          expect(document.undo(), isFalse);
          expect(document.redo(), isFalse);
          input.fillRange(0, input.length, 0);
          final copied = document.copyBackgroundPng()!;
          expect(copied, orderedEquals(fixture.value));
          copied[0] = 0;
          expect(document.copyBackgroundPng(), orderedEquals(fixture.value));
          document.dispose();
          expect(info.byteCount, fixture.value.length);
          expect(copied[1], fixture.value[1]);
          expect(() => document.backgroundInfo, throwsStateError);
          expect(document.copyBackgroundPng, throwsStateError);
        } finally {
          document.dispose();
        }
      });
    }

    test(
      'background survives edit, history branches and detached snapshots',
      () {
        final document = RustDocument.fromBackgroundPng(_rgba);
        try {
          final info = document.backgroundInfo;
          final imageOnly = document.exportProject();
          _addRectangle(document);
          final rectangle = document.strokes.single;
          final withRectangle = document.exportProject();
          document.moveObject(0, 3, 2);
          document.setObjectStyle(
            0,
            rgb: 0xff0000,
            width: 3,
            fillRgb: 0xffee00,
          );
          document.duplicateObject(0, 4, 1);
          document.removeObject(0);
          expect(document.count, 1);
          expect(rectangle.points.first.x, 2);
          expect(document.copyBackgroundPng(), orderedEquals(_rgba));
          expect(identical(document.backgroundInfo, info), isTrue);
          final snapshot = document.strokes;
          document.copyBackgroundPng();
          expect(identical(document.strokes, snapshot), isTrue);
          for (var i = 0; i < 4; i++) {
            expect(document.undo(), isTrue);
          }
          expect(document.exportProject(), orderedEquals(withRectangle));
          expect(document.redo(), isTrue);
          expect(document.undo(), isTrue);
          document.setObjectStyle(0, rgb: 0x111111, width: 2);
          expect(document.canRedo, isFalse);
          expect(document.undo(), isTrue);
          expect(document.undo(), isTrue);
          expect(document.exportProject(), orderedEquals(imageOnly));
          expect(document.copyBackgroundPng(), orderedEquals(_rgba));
        } finally {
          document.dispose();
        }
      },
    );

    test('v3 is self-contained, roundtrips and restores vector undo', () {
      final source = RustDocument.fromBackgroundPng(_rgba);
      _addRectangle(source);
      final project = source.exportProject();
      final expectedProject = Uint8List.fromList(project);
      final expectedSvg = source.exportSvg();
      source.dispose();
      expect(_version(project), 3);
      final reopened = RustDocument.fromProject(project);
      try {
        project.fillRange(0, project.length, 0);
        expect(reopened.exportProject(), orderedEquals(expectedProject));
        expect(reopened.exportSvg(), expectedSvg);
        expect(reopened.copyBackgroundPng(), orderedEquals(_rgba));
        expect(reopened.backgroundInfo!.byteCount, _rgba.length);
        expect(reopened.canRedo, isFalse);
        expect(reopened.undo(), isTrue);
        expect(reopened.count, 0);
        expect(_version(reopened.exportProject()), 3);
        expect(reopened.copyBackgroundPng(), orderedEquals(_rgba));
        expect(reopened.undo(), isFalse);
        expect(reopened.redo(), isTrue);
        expect(reopened.exportSvg(), expectedSvg);
      } finally {
        reopened.dispose();
      }
    });

    test('SVG embeds the exact PNG once beneath vectors', () {
      final document = RustDocument.fromBackgroundPng(_rgba);
      try {
        _addRectangle(document);
        final svg = document.exportSvg();
        final data = RegExp('href="data:image/png;base64,([^"]+)"')
            .allMatches(svg)
            .toList();
        expect(data, hasLength(1));
        expect(base64Decode(data.single[1]!), orderedEquals(_rgba));
        expect(svg.indexOf('<image'), greaterThan(svg.indexOf('<rect')));
        expect(svg.indexOf('<image'), lessThan(svg.indexOf('#123456')));
        expect(svg, contains('viewBox="0 0 32 24"'));
      } finally {
        document.dispose();
      }
    });

    test('vector-only documents still export v2 with absent background', () {
      final document = RustDocument(width: 32, height: 24);
      try {
        expect(document.backgroundInfo, isNull);
        expect(document.copyBackgroundPng(), isNull);
        _addRectangle(document);
        final project = document.exportProject();
        final reopened = RustDocument.fromProject(project);
        try {
          expect(_version(project), 2);
          expect(reopened.backgroundInfo, isNull);
          expect(reopened.copyBackgroundPng(), isNull);
          expect(reopened.exportProject(), orderedEquals(project));
          expect(reopened.exportSvg(), document.exportSvg());
          expect(reopened.exportSvg(), isNot(contains('<image')));
        } finally {
          reopened.dispose();
        }
      } finally {
        document.dispose();
      }
    });

    test('bad PNG candidates preserve existing document and redo', () {
      final document = RustDocument.fromBackgroundPng(_rgb);
      try {
        _addRectangle(document);
        document.undo();
        final before = document.exportProject();
        final info = document.backgroundInfo;
        final corrupt = Uint8List.fromList(_rgba)..[45] ^= 1;
        for (final candidate in [
          Uint8List(0),
          Uint8List(56),
          Uint8List(57),
          corrupt,
          Uint8List.sublistView(_rgba, 0, _rgba.length - 1),
        ]) {
          expect(
            () => RustDocument.fromBackgroundPng(candidate),
            throwsFormatException,
          );
          expect(document.exportProject(), orderedEquals(before));
          expect(document.canRedo, isTrue);
          expect(identical(document.backgroundInfo, info), isTrue);
        }
        expect(document.redo(), isTrue);
      } finally {
        document.dispose();
      }
    });

    test(
      'truncated and corrupt v3 candidates are rejected transactionally',
      () {
        final document = RustDocument.fromBackgroundPng(_rgba);
        try {
          _addRectangle(document);
          final project = document.exportProject();
          final snapshot = document.strokes;
          final corrupt = Uint8List.fromList(project)
            ..[project.length - 5] ^= 1;
          for (final candidate in [
            Uint8List.sublistView(project, 0, 36),
            Uint8List.sublistView(project, 0, 47),
            Uint8List.sublistView(project, 0, project.length - 1),
            corrupt,
          ]) {
            expect(
              () => RustDocument.fromProject(candidate),
              throwsFormatException,
            );
            expect(document.exportProject(), orderedEquals(project));
            expect(identical(document.strokes, snapshot), isTrue);
            expect(document.copyBackgroundPng(), orderedEquals(_rgba));
          }
        } finally {
          document.dispose();
        }
      },
    );
  }, skip: !available);
}
